&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Two paid, week-long organization-wide breaks at mid-year and end-of-year&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:450,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:75}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
